import { SignIn } from "@clerk/nextjs";

export default function SignInPage() {
  return (
    <div className="min-h-screen flex items-center justify-center bg-[#121212]">
      <SignIn
        appearance={{
          elements: {
            rootBox: "mx-auto",
            card: "bg-[#282828] border-[#3E3E3E]",
            headerTitle: "text-white",
            headerSubtitle: "text-[#B3B3B3]",
            socialButtonsBlockButton: "bg-white text-black hover:bg-gray-100",
            formButtonPrimary: "bg-[#FFD700] text-[#121212] hover:bg-[#FFE55C]",
            formFieldInput: "bg-[#181818] text-white border-[#3E3E3E]",
            formFieldLabel: "text-[#B3B3B3]",
            footerActionLink: "text-[#FFD700]",
          },
        }}
      />
    </div>
  );
}
